import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"Privacy","description":"","frontmatter":{"title":"Privacy"},"headers":[],"relativePath":"docs/settings/privacy.md","filePath":"docs/settings/privacy.md","lastUpdated":1794529254000}'),n={name:"docs/settings/privacy.md"};function s(i,e,c,d,p,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p><strong>Settings → Privacy</strong> brings together network activity, update checks, password and disk-protection information, reporting controls and personal information detection settings.</p><h2 id="data-egress" tabindex="-1">Data Egress <a class="header-anchor" href="#data-egress" aria-label="Permalink to &quot;Data Egress&quot;">​</a></h2><p>Review network activity and follow the available links to the relevant service or setting. Local-model inference and online tools are separate: choosing a local model does not turn off tools or services you have enabled.</p><h2 id="updates-and-local-protection" tabindex="-1">Updates and local protection <a class="header-anchor" href="#updates-and-local-protection" aria-label="Permalink to &quot;Updates and local protection&quot;">​</a></h2><p><strong>Version Updates</strong> controls update checks. <strong>Password</strong> manages protection for this local profile; <strong>Disk Encryption</strong> explains the computer&#39;s storage protection. Configure backups separately in <a href="/docs/settings/backup">Settings → Backup</a>.</p><h2 id="usage-and-reliability-reports" tabindex="-1">Usage and reliability reports <a class="header-anchor" href="#usage-and-reliability-reports" aria-label="Permalink to &quot;Usage and reliability reports&quot;">​</a></h2><p><strong>Basic reliability reporting</strong> is on after the reporting notice unless you turn it off. It sends built-in parser and recipe use/error counts and system error counts monthly or when checking for upgrades. Reports exclude persistent app IDs, account details, financial values, file names, raw errors and chat text.</p><p>A separate connection count can record approximate country for downloads and update checks on the cloud side. The app does not read or report your location. Turning basic reporting off stops those connection counts too.</p><p><strong>Enhanced usage and performance reports</strong> are optional. They include broad device/model information, project/source counts, setup progress, monthly active days and performance bands, with a random profile ID separate from your account. They do not include financial records or conversations. No account is needed to share them.</p><p>Use <strong>Preview report</strong> and <strong>View network log</strong> to inspect the reporting information. You can turn reporting off here. <strong>Stop sending and delete reports</strong> stops enhanced reporting and requests deletion; if the cloud is unreachable, the app saves your choice and retries in the background.</p><h2 id="personal-information-detection" tabindex="-1">Personal Information Detection <a class="header-anchor" href="#personal-information-detection" aria-label="Permalink to &quot;Personal Information Detection&quot;">​</a></h2><p>The detection controls save preferences for future detection features. They do <strong>not</strong> currently change or scrub ordinary chats. A cloud model receives the prompts and context used for its answers; choose one only if you trust that provider.</p><p>For a document you intend to share, use the standalone <a href="/docs/tools/pii-redactor">PII Redactor</a> and review its output. See <a href="/docs/privacy-and-security/private-data">Private Data</a> for storage and network details.</p>',14)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
